using System;
using System.Linq;
using System.Collections.Generic;
using Microsoft.EntityFrameworkCore;

namespace DataAccess.DevartRepositories
{
    public partial class EmpresaRepository
    {
        /// <summary>
        /// Devuelve las instituciones educativas filtradas por país y estado/departamento.
        /// Cuando codigoEstado es 0 (kNULL) no filtra por estado.
        /// </summary>
        public virtual ICollection<BusinessLogic.Entities.Empresa> GetInstituciones(
            long codigoPais, long codigoEstado)
        {
            // Para país extranjero sólo se devuelve ORT Uruguay (2898)
            if (codigoPais != 1)
                return objectSet.Where(e => e.CodigoEmpresa == 2898).ToList();

            var query = objectSet
                .Where(e => e.InstitucionEducativa == "SI"
                         && e.CodigoVigencia != "NO"
                         && e.CodigoPais == codigoPais
                         && e.ParaBachilleratoEmpresa == "SI"
                         && (e.CodigoTipoEmpresa == 9 || e.CodigoTipoEmpresa == 10 || e.CodigoTipoEmpresa == 11)
                         && e.CodigoGiroEmpresa != 30);

            if (codigoEstado > 0)
                query = query.Where(e => e.CodigoEstado == codigoEstado);

            return query
                .OrderBy(e => e.NombreMayEmpresa)
                .ToList();
        }

        /// <summary>
        /// Devuelve las empresas marcadas como universidades (ParaGradoEmpresa = SI).
        /// </summary>
        public virtual ICollection<BusinessLogic.Entities.Empresa> GetUniversidades()
        {
            return GetUniversidades(1);
        }

        /// <summary>
        /// Devuelve las universidades para el país indicado.
        /// Para países distintos de Uruguay (1) devuelve únicamente ORT (2898).
        /// </summary>
        public virtual ICollection<BusinessLogic.Entities.Empresa> GetUniversidades(long codigoPais)
        {
            if (codigoPais != 1)
                return objectSet.Where(e => e.CodigoEmpresa == 2898).ToList();

            return objectSet
                .Where(e => (e.InstitucionEducativa == "SI"
                          && e.CodigoVigencia != "NO"
                          && e.CodigoPais == 1
                          && e.CodigoGiroEmpresa == 30
                          && e.CodigoEmpresa != 5539)
                         || e.CodigoEmpresa == 2898)
                .OrderBy(e => e.NombreMayEmpresa)
                .ToList();
        }
    }
